NOTEBOOK_SOURCES = ['# --- notebook setup (delivery glue only) -------------------------------------\n# Runs offline on a memory-aware mock LLM — no OpenAI/Tavily key, no cost.\ntry:\n    import pydantic  # noqa: F401\nexcept ImportError:\n    import subprocess, sys\n    subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", "pydantic"])\n\nfrom pathlib import Path\nPath("data").mkdir(exist_ok=True)\nPath("data/memory_golden_set.jsonl").write_text(r"""{"id": "Q1", "kind": "preference", "memory_effect": "helps", "question": "Summarise the leave policy in my usual format.", "seed": {"preferred_format": "bullets"}, "relevant_key": "preferred_format"}\n{"id": "Q2", "kind": "preference", "memory_effect": "helps", "question": "Give me the expense policy the way I like it.", "seed": {"preferred_format": "bullets"}, "relevant_key": "preferred_format"}\n{"id": "Q3", "kind": "stateless", "memory_effect": "neutral", "question": "What is 15% of 240?", "seed": {"name": "Asha", "team": "HR", "tenure": "3 years", "preferred_format": "bullets"}, "relevant_key": null}\n{"id": "Q4", "kind": "stateless", "memory_effect": "neutral", "question": "How many HR documents are in the knowledge base?", "seed": {"name": "Asha", "team": "HR", "tenure": "3 years", "preferred_format": "bullets"}, "relevant_key": null}\n{"id": "Q5", "kind": "stateless", "memory_effect": "neutral", "question": "What is the standard notice period?", "seed": {"name": "Asha", "team": "HR", "tenure": "3 years", "preferred_format": "bullets"}, "relevant_key": null}\n{"id": "Q6", "kind": "stateless", "memory_effect": "neutral", "question": "Convert 90 minutes to hours.", "seed": {"name": "Asha", "team": "HR", "tenure": "3 years", "preferred_format": "bullets"}, "relevant_key": null}\n{"id": "Q7", "kind": "stateless", "memory_effect": "neutral", "question": "What does the acronym PTO stand for?", "seed": {"name": "Asha", "team": "HR", "tenure": "3 years", "preferred_format": "bullets"}, "relevant_key": null}\n{"id": "Q8", "kind": "stale", "memory_effect": "hurts", "question": "Which project should I focus on this week?", "seed": {"current_project": "Project Atlas"}, "relevant_key": "current_project"}\n{"id": "Q9", "kind": "stale", "memory_effect": "hurts", "question": "Remind me which office I\'m assigned to.", "seed": {"assigned_office": "Building C (closed last quarter)"}, "relevant_key": "assigned_office"}""" + "\\n")\nPath("data/web_fixtures.json").write_text(r"""{\n  "ai agents": [\n    {"title": "State of AI Agents 2026", "snippet": "Agentic systems moved from demos to production in 2026, with tool-use reliability the key differentiator."},\n    {"title": "Agent frameworks roundup", "snippet": "Raw loops and graph-based orchestration remain the two dominant patterns."}\n  ],\n  "openai api": [\n    {"title": "OpenAI API pricing", "snippet": "gpt-4o-mini is positioned as the low-cost tier for high-volume workloads."}\n  ],\n  "cricket": [\n    {"title": "Cricket World Cup — result", "snippet": "The most recent tournament concluded with a closely contested final."}\n  ],\n  "python libraries": [\n    {"title": "Trending Python libraries", "snippet": "Data, LLM-tooling, and async libraries dominate this year\'s trending lists."}\n  ],\n  "announce": [\n    {"title": "OpenAI announcements", "snippet": "Recent announcements focus on tool use, structured outputs, and cost reductions."}\n  ],\n  "_default": [\n    {"title": "Web result", "snippet": "A relevant public-web snippet would appear here (offline fixture)."}\n  ]\n}""" + "\\n")\nprint("wrote the labelled golden set + web fixtures")\n', '#!/usr/bin/env python3\n"""scripts/seed_db.py — (re)create the capstone side database.\n\nW13 gives the assistant structured data to query as a tool. This builds a small\nSQLite database with two tables:\n\n  document_metadata  — one row per document in the knowledge base (the structured\n                       side-table the SQL tool queries)\n  audit_log          — every SQL query the agent runs is logged here (the audit\n                       rail for SQL-as-a-tool)\n\nSQLite is local and offline, so the whole SQL-tool exercise runs with no network\nand no credentials. Run this once (smoke_test.sh does it for you):\n\n    python3 scripts/seed_db.py\n"""\nfrom __future__ import annotations\n\nimport sqlite3\nfrom pathlib import Path\n\nDB_PATH = Path("data/capstone_side.db")   # notebook: local file\n\n# A small, realistic slice of the Enterprise Knowledge Assistant\'s corpus,\n# across the three departments the capstone covers.\nDOCS = [\n    # source, title, doc_type, department, version, updated_at, chunk_count\n    ("hr-001", "Leave & Time-Off Policy",          "policy",   "HR",      "v3", "2026-01-14", 42),\n    ("hr-002", "Code of Conduct",                  "policy",   "HR",      "v2", "2025-11-02", 55),\n    ("hr-003", "Remote Work Guidelines",           "guideline","HR",      "v4", "2026-02-20", 28),\n    ("hr-004", "Onboarding Handbook",              "handbook", "HR",      "v1", "2025-06-30", 90),\n    ("it-001", "Acceptable Use Policy",            "policy",   "IT",      "v5", "2026-01-30", 37),\n    ("it-002", "Security Incident Runbook",        "runbook",  "IT",      "v2", "2026-02-11", 33),\n    ("it-003", "VPN & Access Setup",               "guideline","IT",      "v3", "2025-12-05", 19),\n    ("it-004", "Data Classification Standard",     "standard", "IT",      "v2", "2026-01-08", 24),\n    ("fin-001","Expense Reimbursement Policy",     "policy",   "Finance", "v3", "2026-01-22", 31),\n    ("fin-002","Procurement Guidelines",           "guideline","Finance", "v1", "2025-09-15", 40),\n    ("fin-003","Travel Policy",                    "policy",   "Finance", "v2", "2025-10-19", 26),\n    ("fin-004","Corporate Card Terms",             "terms",    "Finance", "v4", "2026-02-01", 18),\n]\n\n\ndef seed(db_path: Path = DB_PATH) -> Path:\n    db_path.parent.mkdir(parents=True, exist_ok=True)\n    if db_path.exists():\n        db_path.unlink()\n    con = sqlite3.connect(db_path)\n    cur = con.cursor()\n    cur.execute("""\n        CREATE TABLE document_metadata (\n            id           INTEGER PRIMARY KEY,\n            source       TEXT NOT NULL,\n            title        TEXT NOT NULL,\n            doc_type     TEXT NOT NULL,\n            department   TEXT NOT NULL,\n            version      TEXT NOT NULL,\n            updated_at   TEXT NOT NULL,\n            chunk_count  INTEGER NOT NULL\n        )""")\n    cur.executemany(\n        "INSERT INTO document_metadata "\n        "(source,title,doc_type,department,version,updated_at,chunk_count) "\n        "VALUES (?,?,?,?,?,?,?)", DOCS)\n    cur.execute("""\n        CREATE TABLE audit_log (\n            id         INTEGER PRIMARY KEY AUTOINCREMENT,\n            ts         TEXT NOT NULL,\n            actor      TEXT NOT NULL,\n            request    TEXT,\n            sql        TEXT,\n            decision   TEXT NOT NULL,\n            row_count  INTEGER,\n            error      TEXT\n        )""")\n    con.commit()\n    con.close()\n    return db_path\n\nseed()\nprint(\'side-DB built:\', DB_PATH)\n', '"""src/agents/memory.py — state-based memory for the agent.\n\nThe W15 default: a small, explicit **state** the agent remembers about a user\nacross sessions — a Pydantic model, saved to SQLite. This is the right pattern for\nthe large majority of capstones (known, structured facts like a preferred output format). Vector\nand summary memory are more powerful and more complex; see docs/memory_taxonomy.md.\n\nTwo kinds of memory live here:\n  - short-term — the conversation history itself (handled by the agent loop, not stored)\n  - long-term  — this UserState, persisted across sessions\n\nForgetting is deliberate: **TTL** drops stale facts (the sane default), and the user\ncan explicitly forget a fact. Contradiction resolution uses last-write-wins — for a mutable\npreference, a newer write replaces the old (the user is authoritative about their\nown preferences). It is one strategy of several (merge, or keep versioned history);\nscoped to mutable preference facts here, not a universal rule.\n"""\nfrom __future__ import annotations\n\nimport sqlite3\nfrom datetime import date, timedelta\nfrom pathlib import Path\nfrom typing import Callable\n\nfrom pydantic import BaseModel, Field\n\nDEFAULT_DB = Path("data/capstone_side.db")   # notebook: local file (built in setup)\n_today: Callable[[], date] = date.today\n\n\nclass MemoryFact(BaseModel):\n    value: str\n    last_updated: str          # ISO date, e.g. "2026-01-15"\n\n\nclass UserState(BaseModel):\n    """What the agent remembers about one user. `facts` maps a key\n    (e.g. \'preferred_format\') to a value + when it was last set."""\n    user_id: str\n    facts: dict[str, MemoryFact] = Field(default_factory=dict)\n\n    # ── updates (last-write-wins for a mutable pref → contradiction resolution) ──\n    def set(self, key: str, value: str, today: Callable[[], date] = _today) -> None:\n        self.facts[key] = MemoryFact(value=value, last_updated=today().isoformat())\n\n    def get(self, key: str) -> str | None:\n        f = self.facts.get(key)\n        return f.value if f else None\n\n    def forget(self, key: str) -> bool:\n        """User-controlled forgetting — an explicit \'forget X\'."""\n        return self.facts.pop(key, None) is not None\n\n    # ── forgetting strategy: TTL ────────────────────────────────────────────\n    def apply_ttl(self, days: int = 30, today: Callable[[], date] = _today) -> list[str]:\n        """Drop facts whose last_updated is older than `days`. Returns dropped keys."""\n        cutoff = today() - timedelta(days=days)\n        dropped = [k for k, f in self.facts.items()\n                   if date.fromisoformat(f.last_updated) < cutoff]\n        for k in dropped:\n            del self.facts[k]\n        return dropped\n\n    # ── render for the system prompt (short + relevant only) ────────────────\n    def to_prompt(self) -> str:\n        if not self.facts:\n            return ""\n        lines = [f"- {k.replace(\'_\', \' \')}: {f.value}" for k, f in sorted(self.facts.items())]\n        return "What you remember about this user:\\n" + "\\n".join(lines)\n\n\nclass MemoryStore:\n    """SQLite-backed persistence for UserState. One row per (user_id, key)."""\n\n    def __init__(self, db_path: Path | str = DEFAULT_DB):\n        self.db_path = Path(db_path)\n        self._ensure_table()\n\n    def _ensure_table(self) -> None:\n        con = sqlite3.connect(self.db_path)\n        con.execute("""CREATE TABLE IF NOT EXISTS user_memory (\n            user_id TEXT NOT NULL, key TEXT NOT NULL,\n            value TEXT NOT NULL, last_updated TEXT NOT NULL,\n            PRIMARY KEY (user_id, key))""")\n        con.commit(); con.close()\n\n    def load_state(self, user_id: str) -> UserState:\n        con = sqlite3.connect(self.db_path)\n        rows = con.execute("SELECT key, value, last_updated FROM user_memory WHERE user_id=?",\n                           (user_id,)).fetchall()\n        con.close()\n        facts = {k: MemoryFact(value=v, last_updated=lu) for k, v, lu in rows}\n        return UserState(user_id=user_id, facts=facts)\n\n    def save_state(self, state: UserState) -> None:\n        con = sqlite3.connect(self.db_path)\n        con.execute("DELETE FROM user_memory WHERE user_id=?", (state.user_id,))\n        con.executemany(\n            "INSERT INTO user_memory (user_id, key, value, last_updated) VALUES (?,?,?,?)",\n            [(state.user_id, k, f.value, f.last_updated) for k, f in state.facts.items()])\n        con.commit(); con.close()\n\n    def clear(self, user_id: str) -> None:\n        con = sqlite3.connect(self.db_path)\n        con.execute("DELETE FROM user_memory WHERE user_id=?", (user_id,))\n        con.commit(); con.close()\n\n\n# ─── the two hooks the agent loop uses ──────────────────────────────────────\ndef load_for_prompt(store: MemoryStore, user_id: str, ttl_days: int = 30,\n                    today: Callable[[], date] = _today) -> tuple[UserState, str]:\n    """Load state, apply TTL, and render it for the system prompt.\n    Returns (state, prompt_block). Called at the START of a run when memory is on."""\n    state = store.load_state(user_id)\n    dropped = state.apply_ttl(days=ttl_days, today=today)\n    if dropped:\n        store.save_state(state)          # persist the forgetting\n    return state, state.to_prompt()\n\n\ndef update_from_turn(store: MemoryStore, state: UserState, question: str,\n                     today: Callable[[], date] = _today) -> str | None:\n    """User-controlled memory: honour explicit \'remember …\' / \'forget …\' in the\n    user\'s message. Called at the END of a run when memory is on. Returns a note."""\n    q = question.strip()\n    low = q.lower()\n    if low.startswith("remember that "):\n        payload = q[len("remember that "):].strip().rstrip(".")\n        if " is " in payload:\n            key, value = payload.split(" is ", 1)\n            state.set(key.strip().replace(" ", "_"), value.strip(), today=today)\n            store.save_state(state)\n            return f"remembered {key.strip()} = {value.strip()}"\n    if low.startswith("forget "):\n        key = low[len("forget "):].strip().rstrip(".").replace(" ", "_")\n        if state.forget(key):\n            store.save_state(state)\n            return f"forgot {key}"\n    return None\n', '"""src/agents/defenses.py — Failure-Oriented Design, in code.\n\nFive failure categories, five defenses:\n\n    Transient    (429, network blip)        → retry with backoff\n    Permanent    (bad args, bad schema)     → fast-fail (do NOT retry)\n    Silent       (wrong-but-valid result)   → validation / sanity checks (in the tools)\n    Cascading    (timeout floods downstream)→ circuit breaker\n    Adversarial  (injection, misuse)         → tool permissioning (+ sanitisation)\n\n`DefensePolicy.guard(tool_name, call)` wraps a single tool call with permissioning,\na circuit breaker, retry-with-backoff, and graceful degradation, so one bad tool\ncan\'t crash the agent. Deterministic and offline (backoff sleeps are disabled in\ntests via sleep=lambda _: None).\n"""\nfrom __future__ import annotations\n\nimport time\nfrom dataclasses import dataclass, field\nfrom typing import Callable\n\n\n# ─── failure types ──────────────────────────────────────────────────────────\nclass TransientError(Exception):\n    """Temporary — a retry will probably succeed (e.g. network blip)."""\n\n\nclass RateLimited(TransientError):\n    """HTTP 429 — transient, back off and retry."""\n\n\nclass PermanentError(Exception):\n    """Won\'t fix itself — retrying is harmful (bad credentials, bad schema/args)."""\n\n\ndef classify(exc: Exception) -> str:\n    """Map an exception to a failure category (the diagnostic the week teaches)."""\n    if isinstance(exc, RateLimited):\n        return "transient"\n    if isinstance(exc, TransientError) or isinstance(exc, TimeoutError):\n        return "transient"      # timeouts retry, but repeated ones trip the breaker → cascading\n    if isinstance(exc, PermanentError):\n        return "permanent"\n    return "permanent"          # unknown = don\'t blindly retry\n\n\n# ─── circuit breaker (hand-rolled: CLOSED / OPEN / HALF_OPEN) ────────────────\nclass CircuitOpen(Exception):\n    """Raised when the breaker is open and the call is short-circuited."""\n\n\nclass CircuitBreaker:\n    """Opens after `fail_max` consecutive failures; after `reset_timeout` it moves\n    to HALF_OPEN and lets one trial call through. Success closes it; failure\n    re-opens it. This is the cascading-failure defense."""\n\n    def __init__(self, fail_max: int = 3, reset_timeout: float = 30.0,\n                 now: Callable[[], float] = time.monotonic):\n        self.fail_max = fail_max\n        self.reset_timeout = reset_timeout\n        self._now = now\n        self.state = "closed"\n        self.failures = 0\n        self.opened_at = 0.0\n\n    def _can_attempt(self) -> bool:\n        if self.state == "open":\n            if self._now() - self.opened_at >= self.reset_timeout:\n                self.state = "half_open"\n                return True\n            return False\n        return True\n\n    def record_success(self) -> None:\n        self.failures = 0\n        self.state = "closed"\n\n    def record_failure(self) -> None:\n        self.failures += 1\n        if self.failures >= self.fail_max:\n            self.state = "open"\n            self.opened_at = self._now()\n\n    def call(self, fn: Callable[[], str]) -> str:\n        if not self._can_attempt():\n            raise CircuitOpen(f"circuit open (>{self.fail_max} failures)")\n        try:\n            result = fn()\n        except Exception:\n            self.record_failure()\n            raise\n        self.record_success()\n        return result\n\n\n# ─── retry with exponential backoff (the transient defense) ─────────────────\ndef retry_with_backoff(fn: Callable[[], str], attempts: int = 3, base: float = 0.2,\n                       sleep: Callable[[float], None] = time.sleep) -> str:\n    """Retry on TransientError/TimeoutError with exponential backoff. PermanentError\n    is re-raised immediately (fast-fail)."""\n    last: Exception | None = None\n    for i in range(attempts):\n        try:\n            return fn()\n        except PermanentError:\n            raise                                   # never retry a permanent failure\n        except (TransientError, TimeoutError) as e:\n            last = e\n            if i < attempts - 1:\n                sleep(base * (2 ** i))\n    raise last if last else RuntimeError("retry failed")\n\n\n# ─── the policy that wraps every tool call ──────────────────────────────────\n@dataclass\nclass DefensePolicy:\n    retries: int = 3\n    breaker_tools: tuple[str, ...] = ("search_web", "query_sql")   # external / can time out\n    write_tools: tuple[str, ...] = ("send_email",)       # gated behind confirmation\n    fail_max: int = 3\n    sleep: Callable[[float], None] = time.sleep\n    breakers: dict = field(default_factory=dict)\n\n    def __post_init__(self):\n        for t in self.breaker_tools:\n            self.breakers.setdefault(t, CircuitBreaker(fail_max=self.fail_max))\n\n    def guard(self, tool_name: str, call: Callable[[], str]) -> tuple[str, str]:\n        """Run a tool call under the defenses. Returns (observation, status) where\n        status ∈ {ok, degraded, blocked}. Never raises — the agent must survive."""\n        # 1 · Adversarial → tool permissioning: gate side-effecting tools.\n        if tool_name in self.write_tools:\n            return (f"[{tool_name} BLOCKED — requires human confirmation before a "\n                    f"side-effecting action]", "blocked")\n\n        breaker = self.breakers.get(tool_name)\n\n        def attempt() -> str:\n            return breaker.call(call) if breaker else call()\n\n        # 2 · Cascading → if the breaker is already open, degrade fast.\n        try:\n            obs = retry_with_backoff(attempt, attempts=self.retries, sleep=self.sleep)\n            return obs, "ok"\n        except CircuitOpen as e:\n            return (f"[{tool_name} unavailable — {e}; answering without it]", "degraded")\n        except Exception as e:                       # transient exhausted / permanent\n            cat = classify(e)\n            return (f"[{tool_name} failed ({cat}: {e}); answering without it]", "degraded")\n', '"""src/agents/mock_llm.py — the LLM behind the agent, and how we mock it.\n\nThe single most useful testing skill this week is **mocking the LLM**. A real LLM\ncall is slow, costs money, and is non-deterministic — useless in a test. So the\nagent talks to a tiny interface:\n\n    llm.complete(messages, tools) -> LLMResponse   # either a tool call or a final answer\n\nTwo implementations:\n  MockLLM  — deterministic and offline. Give it a *script* (a fixed list of\n             responses, for tests) or let it keyword-route one tool call then a\n             final answer (for offline runs). No network, no key, milliseconds.\n  OpenAILLM — the real thing (OpenAI function calling). Needs OPENAI_API_KEY.\n\nEverything in this package runs on MockLLM, which is why the whole thing — agent,\ndefenses, the five failure scenarios, the test suite — works with no credentials.\n"""\nfrom __future__ import annotations\n\nimport json\nimport re\nfrom dataclasses import dataclass\nfrom typing import Callable\n\n# Tool is defined in the cell above\n\n\n@dataclass\nclass LLMResponse:\n    kind: str                      # "tool_use" | "final"\n    tool_name: str | None = None\n    tool_args: dict | None = None\n    content: str | None = None\n\n    @staticmethod\n    def tool(name: str, **args) -> "LLMResponse":\n        return LLMResponse("tool_use", tool_name=name, tool_args=args)\n\n    @staticmethod\n    def final(content: str) -> "LLMResponse":\n        return LLMResponse("final", content=content)\n\n\nclass MockLLM:\n    """A deterministic stand-in for a function-calling LLM.\n\n    - Scripted:  MockLLM(script=[LLMResponse.tool(\'calculate\', expression=\'2+2\'),\n                                 LLMResponse.final(\'It is 4.\')])\n                 returns those in order (extra calls repeat the last one).\n    - Keyword:   MockLLM()  → routes ONE tool call by keyword, then a final answer\n                 synthesised from the observation. Good for offline demos.\n    """\n\n    def __init__(self, script: list[LLMResponse] | None = None,\n                 router: Callable[[list[dict], list[Tool]], LLMResponse] | None = None):\n        self.script = list(script) if script else None\n        self.router = router\n        self.calls = 0\n\n    def complete(self, messages: list[dict], tools: list[Tool]) -> LLMResponse:\n        self.calls += 1\n        if self.script is not None:\n            return self.script.pop(0) if self.script else LLMResponse.final(\n                "(no more scripted responses)")\n        if self.router is not None:\n            return self.router(messages, tools)\n        return self._keyword_route(messages, tools)\n\n    # ── default keyword routing: one tool call, then a final answer ──────────\n    def _keyword_route(self, messages: list[dict], tools: list[Tool]) -> LLMResponse:\n        # If a tool has already produced an observation, answer from it.\n        obs = _last_observation(messages)\n        if obs is not None:\n            return LLMResponse.final(f"Based on the tool result: {obs}")\n        q = _last_user(messages).lower()\n        names = {t.name for t in tools}\n        if "calculate" in names and re.search(r"\\d\\s*[-+*/%]\\s*\\d|percent|%|how much is", q):\n            return LLMResponse.tool("calculate", expression=_extract_expr(q))\n        sql_kw = ("how many doc", "which department", "what version", "list the", "count",\n                  "how many hr", "how many it", "how many finance", "updated", "chunk")\n        if "query_sql" in names and any(k in q for k in sql_kw):\n            return LLMResponse.tool("query_sql",\n                                    sql="SELECT COUNT(*) AS total_documents FROM document_metadata",\n                                    purpose="metadata question")\n        web_kw = ("latest", "current", "today", "news", "price", "recent", "2026", "who won")\n        if "search_web" in names and any(k in q for k in web_kw):\n            return LLMResponse.tool("search_web", query=_last_user(messages), max_results=3)\n        return LLMResponse.final("I can answer that directly: (no tool needed).")\n\n\n# ─── real OpenAI adapter (needs a key + network) ────────────────────────────\nclass OpenAILLM:\n    def __init__(self, model: str = "gpt-5-mini"):\n        from openai import OpenAI\n        self.client = OpenAI()\n        self.model = model\n\n    def complete(self, messages: list[dict], tools: list[Tool]) -> LLMResponse:\n        resp = self.client.chat.completions.create(\n            model=self.model, messages=messages,\n            tools=[t.openai_schema() for t in tools], tool_choice="auto")\n        msg = resp.choices[0].message\n        if msg.tool_calls:\n            call = msg.tool_calls[0]\n            return LLMResponse.tool(call.function.name, **json.loads(call.function.arguments or "{}"))\n        return LLMResponse.final(msg.content or "")\n\n\n# ─── tiny helpers ───────────────────────────────────────────────────────────\ndef _last_user(messages: list[dict]) -> str:\n    for m in reversed(messages):\n        if m.get("role") == "user":\n            return str(m.get("content", ""))\n    return ""\n\n\ndef _last_observation(messages: list[dict]) -> str | None:\n    for m in reversed(messages):\n        if m.get("role") == "tool":\n            return str(m.get("content", ""))\n    return None\n\n\ndef _extract_expr(q: str) -> str:\n    m = re.search(r"[0-9][0-9\\.\\s\\+\\-\\*/%\\(\\)]*[0-9\\)]", q)\n    return m.group(0).strip() if m else "0"\n', '"""src/agents/tools/base.py — the Tool contract.\n\nA tool an LLM can call reliably is four things done well (the W13 principles):\n  1. a good NAME       — a verb, specific, snake_case\n  2. a typed SCHEMA    — a Pydantic model: required fields, sensible defaults\n  3. a DESCRIPTION     — written for the *model*, saying WHEN to use the tool\n  4. IDEMPOTENCY        — declared, so the loop knows if a retry is safe\n\nEvery tool subclasses `Tool`, sets those four, and implements `run`. The same\ndefinition exports to both OpenAI function-calling and Anthropic tool-use schemas.\n"""\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom pydantic import BaseModel\n\n\nclass Tool:\n    name: str = ""\n    description: str = ""\n    Args: type[BaseModel] = BaseModel\n    idempotent: bool = True          # is calling this twice with the same args safe?\n    has_side_effects: bool = False   # does it change external state?\n\n    def run(self, **kwargs: Any) -> str:\n        raise NotImplementedError\n\n    # ── validation + execution ────────────────────────────────────────────\n    def call(self, arguments: dict[str, Any]) -> str:\n        """Validate arguments against the schema, then run."""\n        args = self.Args(**(arguments or {}))\n        return self.run(**args.model_dump())\n\n    # ── provider schema exports ───────────────────────────────────────────\n    def parameters_schema(self) -> dict:\n        return self.Args.model_json_schema()\n\n    def openai_schema(self) -> dict:\n        return {"type": "function",\n                "function": {"name": self.name,\n                             "description": self.description,\n                             "parameters": self.parameters_schema()}}\n\n    def anthropic_schema(self) -> dict:\n        return {"name": self.name,\n                "description": self.description,\n                "input_schema": self.parameters_schema()}\n', '"""src/agents/tools/calculate.py — a computation tool.\n\nDeterministic, offline, and safe: it evaluates an arithmetic expression with a\nsmall AST walker (no `eval`), so an LLM can hand it a calculation and get a\nreliable number back. Idempotent and side-effect-free — the easy end of the\ntool spectrum, and a good first example of a well-formed tool.\n"""\nfrom __future__ import annotations\n\nimport ast\nimport operator\n\nfrom pydantic import BaseModel, Field\n\n# Tool is defined in the cell above\n\n_OPS = {\n    ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,\n    ast.Div: operator.truediv, ast.Mod: operator.mod, ast.Pow: operator.pow,\n    ast.USub: operator.neg, ast.UAdd: operator.pos, ast.FloorDiv: operator.floordiv,\n}\n\n\ndef _eval(node: ast.AST) -> float:\n    if isinstance(node, ast.Expression):\n        return _eval(node.body)\n    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):\n        return node.value\n    if isinstance(node, ast.BinOp) and type(node.op) in _OPS:\n        return _OPS[type(node.op)](_eval(node.left), _eval(node.right))\n    if isinstance(node, ast.UnaryOp) and type(node.op) in _OPS:\n        return _OPS[type(node.op)](_eval(node.operand))\n    raise ValueError("unsupported expression — only + - * / % ** ( ) and numbers")\n\n\nclass CalculateArgs(BaseModel):\n    expression: str = Field(\n        ..., description="An arithmetic expression, e.g. \'1350 * 0.18\' or \'(42 + 8) / 2\'.")\n\n\nclass CalculateTool(Tool):\n    name = "calculate"\n    description = ("Evaluate an arithmetic expression and return the numeric result. "\n                   "Use this whenever a question needs exact math — sums, differences, "\n                   "products, division, percentages, or powers. Do NOT use it to look up "\n                   "facts; it only does arithmetic on numbers you provide.")\n    Args = CalculateArgs\n    idempotent = True\n    has_side_effects = False\n\n    def run(self, expression: str) -> str:\n        try:\n            result = _eval(ast.parse(expression, mode="eval"))\n        except Exception as e:  # noqa: BLE001 - report cleanly to the agent\n            return f"calculate error: {e}"\n        if isinstance(result, float) and result.is_integer():\n            result = int(result)\n        return f"{expression} = {result}"\n', '"""src/agents/tools/query_sql.py — SQL as a tool, safely.\n\nLetting an LLM run SQL is powerful and dangerous. This tool ships the three rails\nevery SQL-as-a-tool needs in production:\n\n  1. AUDIT LOGGING     — every query (allowed or denied) is written to audit_log\n  2. READ-ONLY DEFAULT  — only a single SELECT / WITH…SELECT is permitted\n  3. CONSTRAINED UPDATES — writes/DDL (INSERT/UPDATE/DELETE/DROP/…) are denied\n                          outright (write access is a W18 topic, gated behind\n                          injection defenses and a human-approval step)\n\nEverything runs against a local SQLite database, so it works offline with no\ncredentials. The migration path to Postgres is a config change, not a rewrite\n(see docs/runbooks/sql_as_a_tool_safety.md).\n"""\nfrom __future__ import annotations\n\nimport re\nimport sqlite3\nfrom datetime import datetime, timezone\nfrom pathlib import Path\n\nfrom pydantic import BaseModel, Field\n\n# Tool is defined in the cell above\n\nDB_PATH = Path("data/capstone_side.db")   # notebook: local file\n\n# Statements that change data or schema — denied by the read-only rail.\n_FORBIDDEN = {"insert", "update", "delete", "drop", "alter", "create", "replace",\n              "truncate", "attach", "detach", "pragma", "vacuum", "reindex",\n              "grant", "revoke", "begin", "commit"}\n_MAX_ROWS = 50\n\n\ndef _strip_comments(sql: str) -> str:\n    sql = re.sub(r"--[^\\n]*", " ", sql)\n    sql = re.sub(r"/\\*.*?\\*/", " ", sql, flags=re.S)\n    return sql.strip()\n\n\ndef is_read_only(sql: str) -> tuple[bool, str]:\n    """Return (ok, reason). Only a single SELECT/WITH…SELECT is allowed."""\n    clean = _strip_comments(sql)\n    if not clean:\n        return False, "empty query"\n    statements = [s for s in clean.split(";") if s.strip()]\n    if len(statements) > 1:\n        return False, "multiple statements are not allowed"\n    first = statements[0].lstrip().split(None, 1)[0].lower()\n    if first not in ("select", "with"):\n        return False, f"only SELECT queries are allowed (got \'{first.upper()}\')"\n    words = set(re.findall(r"[a-z_]+", clean.lower()))\n    hit = words & _FORBIDDEN\n    if hit:\n        return False, f"write/DDL keyword not permitted: {\', \'.join(sorted(hit))}"\n    return True, "ok"\n\n\nclass QuerySqlArgs(BaseModel):\n    sql: str = Field(..., description="A single read-only SQL SELECT query over the "\n                                      "document_metadata table.")\n    purpose: str = Field("", description="One phrase describing what the query is for "\n                                         "(recorded in the audit log).")\n\n\nclass QuerySqlTool(Tool):\n    name = "query_sql"\n    description = (\n        "Run a read-only SQL SELECT against the knowledge-base metadata database and "\n        "return the rows. Use this for questions about the DOCUMENTS THEMSELVES — how "\n        "many documents exist, which department owns them, their type, version, "\n        "chunk_count, or when they were last updated. Table: document_metadata"\n        "(id, source, title, doc_type, department, version, updated_at, chunk_count). "\n        "Do NOT use it to answer questions about document CONTENTS — only their metadata.")\n    Args = QuerySqlArgs\n    idempotent = True            # SELECTs don\'t change state\n    has_side_effects = False\n\n    def __init__(self, db_path: Path | str = DB_PATH):\n        self.db_path = Path(db_path)\n\n    def _audit(self, request: str, sql: str, decision: str,\n               row_count: int | None, error: str | None) -> None:\n        con = sqlite3.connect(self.db_path)\n        con.execute(\n            "INSERT INTO audit_log (ts, actor, request, sql, decision, row_count, error) "\n            "VALUES (?,?,?,?,?,?,?)",\n            (datetime.now(timezone.utc).isoformat(timespec="seconds"), "agent",\n             request, sql, decision, row_count, error))\n        con.commit()\n        con.close()\n\n    def run(self, sql: str, purpose: str = "") -> str:\n        ok, reason = is_read_only(sql)\n        if not ok:\n            self._audit(purpose, sql, "denied", None, reason)\n            return (f"query_sql DENIED: {reason}. This tool is read-only; write access "\n                    f"is not available. (Logged to the audit trail.)")\n        try:\n            con = sqlite3.connect(self.db_path)\n            cur = con.execute(sql)\n            rows = cur.fetchmany(_MAX_ROWS)\n            cols = [d[0] for d in cur.description] if cur.description else []\n            con.close()\n        except Exception as e:  # noqa: BLE001\n            self._audit(purpose, sql, "error", None, str(e))\n            return f"query_sql error: {e}"\n        self._audit(purpose, sql, "allowed", len(rows), None)\n        if not rows:\n            return "query_sql: (0 rows)"\n        header = " | ".join(cols)\n        body = "\\n".join(" | ".join(str(v) for v in r) for r in rows)\n        more = "" if len(rows) < _MAX_ROWS else f"\\n… (capped at {_MAX_ROWS} rows)"\n        return f"{header}\\n{\'-\' * len(header)}\\n{body}{more}"\n', '"""src/agents/tools/search_web.py — an external-API tool (web search).\n\nWraps a web-search API (Tavily) so the agent can reach information beyond the\nknowledge base — current events, prices, anything not in the corpus. This is the\n"API-calling agent" pattern: the LLM decides it needs fresh external info and\ncalls out.\n\nWeb search has real cost and latency, so the description tells the model to use\nit only when the answer isn\'t in the corpus. For offline runs and tests, the tool\nfalls back to a local fixture file, so the whole thing works with no network and\nno TAVILY_API_KEY.\n"""\nfrom __future__ import annotations\n\nimport json\nimport os\nfrom pathlib import Path\n\nfrom pydantic import BaseModel, Field\n\n# Tool is defined in the cell above\n\nFIXTURES_PATH = Path("data/web_fixtures.json")   # notebook: local file\n\n\nclass SearchWebArgs(BaseModel):\n    query: str = Field(..., description="A concise web-search query.")\n    max_results: int = Field(3, ge=1, le=5, description="How many results to return.")\n\n\nclass SearchWebTool(Tool):\n    name = "search_web"\n    description = (\n        "Search the public web and return short result snippets. Use this ONLY when the "\n        "answer is not in the internal knowledge base — for current events, live figures, "\n        "recent releases, or anything outside company documents. It has cost and latency, "\n        "so prefer the internal tools when they can answer. Returns titles and snippets, "\n        "not full pages.")\n    Args = SearchWebArgs\n    idempotent = True            # reading search results doesn\'t change state\n    has_side_effects = False\n\n    def __init__(self, offline: bool | None = None):\n        # offline when explicitly set, or when there is no API key available\n        self.offline = (not os.environ.get("TAVILY_API_KEY")) if offline is None else offline\n\n    def _fixture(self, query: str, k: int) -> str:\n        try:\n            data = json.loads(FIXTURES_PATH.read_text())\n        except Exception:\n            data = {"_default": [{"title": "No fixture", "snippet": "offline stub result."}]}\n        results = None\n        for key, res in data.items():\n            if key != "_default" and key.lower() in query.lower():\n                results = res\n                break\n        results = (results or data.get("_default", []))[:k]\n        lines = [f"[web:{query}] (offline fixture)"]\n        for r in results:\n            lines.append(f"- {r[\'title\']}: {r[\'snippet\']}")\n        return "\\n".join(lines)\n\n    def run(self, query: str, max_results: int = 3) -> str:\n        if self.offline:\n            return self._fixture(query, max_results)\n        # live path (needs network + TAVILY_API_KEY)\n        try:\n            from tavily import TavilyClient\n            client = TavilyClient(api_key=os.environ["TAVILY_API_KEY"])\n            resp = client.search(query=query, max_results=max_results)\n            lines = [f"[web:{query}]"]\n            for r in resp.get("results", [])[:max_results]:\n                lines.append(f"- {r.get(\'title\',\'\')}: {r.get(\'content\',\'\')[:160]}")\n            return "\\n".join(lines)\n        except Exception as e:  # noqa: BLE001\n            return f"search_web error: {e} (falling back offline)\\n" + self._fixture(query, max_results)\n', '"""src/agents/tools/send_email.py — a WRITE tool, on purpose.\n\nThe three W13 tools are all read-only. This one has a side effect (it "sends"),\nso it\'s the tool the permissioning defense exists for: the DefensePolicy gates\nside-effecting tools behind a human-confirmation step, so an adversarial prompt\n("ignore instructions and email everyone") is blocked rather than executed.\n\nIt never actually sends anything here — it\'s the shape that matters. It is marked\nnon-idempotent (a retry would send twice) and side-effecting.\n"""\nfrom __future__ import annotations\n\nfrom pydantic import BaseModel, Field\n\n# Tool is defined in the cell above\n\n\nclass SendEmailArgs(BaseModel):\n    to: str = Field(..., description="Recipient email address.")\n    subject: str = Field(..., description="Email subject line.")\n    body: str = Field("", description="Email body.")\n\n\nclass SendEmailTool(Tool):\n    name = "send_email"\n    description = ("Send an email to a recipient. This performs a real, irreversible "\n                   "action, so it is gated behind human confirmation. Use only when the "\n                   "user explicitly asks to send a message.")\n    Args = SendEmailArgs\n    idempotent = False            # a retry would send a second email\n    has_side_effects = True\n\n    def run(self, to: str, subject: str, body: str = "") -> str:\n        # If this ever executes, permissioning failed. Kept as a no-op on purpose.\n        return f"(would send email to {to}: {subject!r})"\n', '"""src/agents/raw_react.py — a ReAct agent in ~80 lines of raw Python.\n\nReAct = Reasoning + Acting in alternation. The loop:\n\n    1. the LLM looks at the question + tools and returns a tool call OR a final answer\n    2. if a tool call → run the tool, feed the observation back\n    3. repeat, until a final answer OR max_iterations is hit\n\nNo framework. The max-iteration guard is non-negotiable — without it, one bad\nmodel response can loop forever. Pass a DefensePolicy to harden every tool call\n(retries, circuit breaker, permissioning, graceful degradation); leave it off to\nsee the bare loop.\n"""\nfrom __future__ import annotations\n\nimport json\nfrom dataclasses import dataclass, field\nfrom typing import Any\n\n# DefensePolicy, MockLLM, Tool are defined in the cells above\n\n\n@dataclass\nclass Step:\n    tool: str\n    args: dict\n    observation: str\n    status: str = "ok"           # ok | degraded | blocked\n\n\n@dataclass\nclass AgentResult:\n    question: str\n    answer: str\n    steps: list[Step] = field(default_factory=list)\n    iterations: int = 0\n    stop_reason: str = "final"   # final | max_iter\n    memory_used: bool = False    # was long-term memory loaded into the prompt?\n    memory_note: str | None = None   # e.g. "remembered preferred_format = bullets"\n    prompt_chars: int = 0        # total prompt characters processed (a cost proxy)\n    def to_dict(self) -> dict:\n        return {"question": self.question, "answer": self.answer,\n                "iterations": self.iterations, "stop_reason": self.stop_reason,\n                "memory_used": self.memory_used, "memory_note": self.memory_note,\n                "prompt_chars": self.prompt_chars,\n                "steps": [s.__dict__ for s in self.steps]}\n\n\nSYSTEM = ("You are a helpful assistant that can call tools. Think about whether a "\n          "tool is needed; call one if so, otherwise answer directly. Never invent "\n          "tool results.")\n\n\nclass ReActAgent:\n    def __init__(self, llm: Any, tools: list[Tool], max_iter: int = 5,\n                 defenses: DefensePolicy | None = None,\n                 memory: Any = None, user_id: str = "default", ttl_days: int = 30,\n                 today: Any = None):\n        self.llm = llm\n        self.tools = tools\n        self.by_name = {t.name: t for t in tools}\n        self.max_iter = max_iter\n        self.defenses = defenses\n        self.memory = memory            # a MemoryStore, or None = memory OFF\n        self.user_id = user_id\n        self.ttl_days = ttl_days\n        self.today = today              # injectable clock (tests)\n\n    def _execute(self, name: str, args: dict) -> tuple[str, str]:\n        tool = self.by_name.get(name)\n        if tool is None:\n            return f"[unknown tool \'{name}\']", "degraded"\n        # PermanentError, RateLimited, TransientError are defined above\n\n        def call() -> str:\n            try:\n                return tool.call(args or {})\n            except (RateLimited, TransientError, TimeoutError):\n                raise                             # let the policy retry / trip the breaker\n            except PermanentError:\n                raise                             # already classified\n            except Exception as e:                # bad/hallucinated args, bad schema = permanent\n                raise PermanentError(str(e))\n\n        if self.defenses:\n            return self.defenses.guard(name, call)\n        return call(), "ok"                       # bare loop (no defenses)\n\n    def run(self, question: str) -> AgentResult:\n        result = AgentResult(question=question, answer="")\n        # ── long-term memory: load state, apply TTL, inject into the system prompt ──\n        system = SYSTEM\n        state = None\n        if self.memory is not None:\n            # load_for_prompt is defined in the memory cell above\n            kw = {"ttl_days": self.ttl_days}\n            if self.today is not None:\n                kw["today"] = self.today\n            state, mem_block = load_for_prompt(self.memory, self.user_id, **kw)\n            if mem_block:\n                system = SYSTEM + "\\n\\n" + mem_block\n                result.memory_used = True\n        messages = [{"role": "system", "content": system},\n                    {"role": "user", "content": question}]\n        for i in range(self.max_iter):\n            result.iterations = i + 1\n            result.prompt_chars += sum(len(str(m.get("content") or "")) for m in messages)\n            resp = self.llm.complete(messages, self.tools)\n            if resp.kind == "final":\n                result.answer = resp.content or ""\n                result.stop_reason = "final"\n                break\n            # tool call\n            name, args = resp.tool_name, resp.tool_args or {}\n            obs, status = self._execute(name, args)\n            result.steps.append(Step(tool=name, args=args, observation=obs, status=status))\n            call_id = f"call_{i}"\n            messages.append({"role": "assistant", "content": None,\n                             "tool_calls": [{"id": call_id, "type": "function",\n                                             "function": {"name": name,\n                                                          "arguments": json.dumps(args)}}]})\n            messages.append({"role": "tool", "tool_call_id": call_id, "content": obs})\n        else:\n            # max-iteration guard fired\n            result.stop_reason = "max_iter"\n            result.answer = ("(stopped after the maximum number of steps — I couldn\'t reach a "\n                             "final answer safely.)")\n        # ── user-controlled memory: honour \'remember …\' / \'forget …\' ──\n        if self.memory is not None and state is not None:\n            # update_from_turn is defined in the memory cell above\n            kw = {"today": self.today} if self.today is not None else {}\n            result.memory_note = update_from_turn(self.memory, state, question, **kw)\n        return result\n\n\n# ─── assembly ───────────────────────────────────────────────────────────────\ndef default_tools(offline: bool = True) -> list[Tool]:\n    # the four Tool classes are defined in the cells above\n    return [SearchWebTool(offline=offline), QuerySqlTool(), CalculateTool(), SendEmailTool()]\n\n\ndef build_agent(offline: bool = True, use_llm: bool = False, hardened: bool = True,\n                max_iter: int = 5, memory: bool = False, user_id: str = "default",\n                ttl_days: int = 30, today: Any = None) -> ReActAgent:\n    """Default: offline MockLLM + hardened with the DefensePolicy. Set memory=True to\n    attach the long-term state layer (SQLite-backed)."""\n    tools = default_tools(offline=offline)\n    if use_llm:\n        # OpenAILLM is defined above\n        llm: Any = OpenAILLM()\n    else:\n        llm = MockLLM()\n    policy = DefensePolicy() if hardened else None\n    store = None\n    if memory:\n        # MemoryStore is defined in the memory cell above\n        store = MemoryStore()\n    return ReActAgent(llm, tools, max_iter=max_iter, defenses=policy,\n                      memory=store, user_id=user_id, ttl_days=ttl_days, today=today)\n', '#!/usr/bin/env python3\n"""scripts/memory_eval.py — does memory help or hurt? Measure it honestly.\n\nThe W15 honesty moment. Runs a labelled golden set through the agent TWICE — once\nwith long-term memory ON, once OFF — and compares correctness and prompt cost. The\nanswer is usually uncomfortable: memory helps on a few questions, hurts on some,\nand adds cost on the rest.\n\n    python3 scripts/memory_eval.py compare            # the full on/off table + verdict\n    python3 scripts/memory_eval.py run Q1             # one question, both modes\n    python3 scripts/memory_eval.py grade Q8 hurts     # check your classification\n    python3 scripts/memory_eval.py verdict            # the data-driven verdict\n    python3 scripts/memory_eval.py answers            # answer key (instructors)\n\nFully offline: a memory-aware mock LLM makes the effect deterministic. The point is\nthe *discipline* (prove it before adopting), not the specific mock numbers.\n"""\nfrom __future__ import annotations\n\nimport json\nimport sys\nfrom datetime import date\nfrom pathlib import Path\n\n\n# seed is defined in the setup cell above\n# MemoryStore, UserState defined above\n# LLMResponse defined above\n# ReActAgent, default_tools defined above\n\nGOLDEN = Path("data/memory_golden_set.jsonl")   # notebook: local file (written in setup)\nTODAY = date(2026, 1, 15)                 # fixed clock → deterministic\n\n\ndef load_golden() -> list[dict]:\n    return [json.loads(l) for l in GOLDEN.read_text().splitlines() if l.strip()]\n\n\n# ─── a memory-aware mock LLM ────────────────────────────────────────────────\ndef make_router(entry: dict):\n    """Return a router whose answer depends on the question kind AND on whether the\n    relevant fact is present in the system prompt (i.e. whether memory was on)."""\n    kind = entry["kind"]\n    key = entry.get("relevant_key")\n\n    def router(messages, tools):\n        system = next((m["content"] for m in messages if m["role"] == "system"), "")\n        fact_present = bool(key) and (key.replace("_", " ") in system)\n        if kind == "preference":\n            if fact_present:\n                return LLMResponse.final("[personalized] Here it is, formatted as bullet points.")\n            return LLMResponse.final("[generic] Here it is (default prose format).")\n        if kind == "stale":\n            if fact_present:\n                return LLMResponse.final("[stale] Based on what I have stored, proceed as before.")\n            return LLMResponse.final("[current] I don\'t have that stored; let\'s confirm the current value.")\n        # stateless — memory is irrelevant to the answer\n        return LLMResponse.final("[answer] Done — computed directly.")\n    return router\n\n\ndef is_correct(entry: dict, answer: str) -> bool:\n    kind = entry["kind"]\n    if kind == "preference":\n        return "[personalized]" in answer      # only right when memory supplied the preference\n    if kind == "stale":\n        return "[stale]" not in answer          # right only when it did NOT use the stale fact\n    return True                                 # stateless: always answerable\n\n\n# ─── run one question in one mode ───────────────────────────────────────────\ndef run_one(entry: dict, memory_on: bool) -> dict:\n    llm_router = make_router(entry)\n    # MockLLM is defined above\n    llm = MockLLM(router=llm_router)\n    if memory_on:\n        store = MemoryStore()\n        uid = f"eval_{entry[\'id\']}"\n        store.clear(uid)\n        state = UserState(user_id=uid)\n        for k, v in entry.get("seed", {}).items():\n            state.set(k, v, today=lambda: TODAY)\n        store.save_state(state)\n        agent = ReActAgent(llm, default_tools(offline=True), memory=store,\n                           user_id=uid, today=lambda: TODAY)\n    else:\n        agent = ReActAgent(llm, default_tools(offline=True), memory=None)\n    r = agent.run(entry["question"])\n    return {"answer": r.answer, "correct": is_correct(entry, r.answer),\n            "prompt_chars": r.prompt_chars,\n            "tool_ok": all(s.status != "blocked" for s in r.steps)}\n\n\ndef classify_effect(entry: dict) -> str:\n    on = run_one(entry, True)["correct"]\n    off = run_one(entry, False)["correct"]\n    if on and not off:\n        return "helps"\n    if off and not on:\n        return "hurts"\n    return "neutral"\n\n\n# ─── the comparison ─────────────────────────────────────────────────────────\ndef _summary(rows: list[dict]) -> dict:\n    n = len(rows)\n    on_acc = sum(r["on"]["correct"] for r in rows) / n\n    off_acc = sum(r["off"]["correct"] for r in rows) / n\n    on_cost = sum(r["on"]["prompt_chars"] for r in rows) / n\n    off_cost = sum(r["off"]["prompt_chars"] for r in rows) / n\n    effects = [r["effect"] for r in rows]\n    return {"n": n, "on_acc": on_acc, "off_acc": off_acc, "on_cost": on_cost,\n            "off_cost": off_cost, "helps": effects.count("helps"),\n            "hurts": effects.count("hurts"), "neutral": effects.count("neutral")}\n\n\ndef _rows() -> list[dict]:\n    out = []\n    for e in load_golden():\n        on, off = run_one(e, True), run_one(e, False)\n        effect = "helps" if (on["correct"] and not off["correct"]) else \\\n                 "hurts" if (off["correct"] and not on["correct"]) else "neutral"\n        out.append({"e": e, "on": on, "off": off, "effect": effect})\n    return out\n\n\ndef make_verdict(s: dict) -> str:\n    cost_delta = (s["on_cost"] - s["off_cost"]) / max(s["off_cost"], 1) * 100\n    acc_line = (f"correctness on={s[\'on_acc\']:.2f} vs off={s[\'off_acc\']:.2f}")\n    cost_line = f"prompt cost +{cost_delta:.0f}% with memory on"\n    if s["on_acc"] > s["off_acc"] + 0.05 and s["hurts"] == 0:\n        head = "KEEP — memory improved correctness at acceptable cost."\n    elif s["hurts"] > 0 and s["on_acc"] <= s["off_acc"] + 0.05:\n        head = ("LIMITED / DROP for general use — memory did not improve overall "\n                f"correctness and added cost. Keep it ONLY scoped to stable preference "\n                f"facts (helped on {s[\'helps\']}), never for changing state "\n                f"(hurt on {s[\'hurts\']} stale-context questions).")\n    else:\n        head = "MIXED — memory helps in narrow cases; scope it deliberately."\n    return f"{head}\\n  ({acc_line}; {cost_line}; helps {s[\'helps\']} / hurts {s[\'hurts\']} / neutral {s[\'neutral\']})"\n\n\ndef cmd_compare() -> int:\n    seed()\n    rows = _rows()\n    print("\\n  Memory ON vs OFF — the honest comparison\\n  " + "=" * 62)\n    print(f"  {\'ID\':<4}{\'kind\':<12}{\'on✓\':<5}{\'off✓\':<6}{\'on chars\':<10}{\'off chars\':<11}effect")\n    print("  " + "-" * 62)\n    for r in rows:\n        print(f"  {r[\'e\'][\'id\']:<4}{r[\'e\'][\'kind\']:<12}"\n              f"{\'Y\' if r[\'on\'][\'correct\'] else \'n\':<5}{\'Y\' if r[\'off\'][\'correct\'] else \'n\':<6}"\n              f"{r[\'on\'][\'prompt_chars\']:<10}{r[\'off\'][\'prompt_chars\']:<11}{r[\'effect\']}")\n    s = _summary(rows)\n    print("  " + "-" * 62)\n    print(f"  VERDICT: {make_verdict(s)}\\n")\n    return 0\n\n\ndef cmd_run(qid: str) -> int:\n    e = next((x for x in load_golden() if x["id"] == qid), None)\n    if not e:\n        print(f"no such question \'{qid}\'"); return 1\n    on, off = run_one(e, True), run_one(e, False)\n    print(f"\\n### {e[\'id\']} ({e[\'kind\']}) — {e[\'question\']}")\n    print(f"  memory ON : correct={on[\'correct\']}  chars={on[\'prompt_chars\']}")\n    print(f"              {on[\'answer\']}")\n    print(f"  memory OFF: correct={off[\'correct\']}  chars={off[\'prompt_chars\']}")\n    print(f"              {off[\'answer\']}")\n    print(f"  → effect: {classify_effect(e)}")\n    return 0\n\n\ndef cmd_grade(qid: str, guess: str) -> int:\n    e = next((x for x in load_golden() if x["id"] == qid), None)\n    if not e:\n        print(f"no such question \'{qid}\'"); return 1\n    g = (guess or "").strip().lower()\n    if g not in ("helps", "hurts", "neutral"):\n        print("pick: helps, hurts, or neutral"); return 1\n    actual = e["memory_effect"]\n    if g == actual:\n        print(f"✓ Correct — {actual}."); return 0\n    print(f"✗ Not {g}. Re-run it: python3 scripts/memory_eval.py run {qid}"); return 1\n\n\ndef cmd_verdict() -> int:\n    seed()\n    print("\\n  " + make_verdict(_summary(_rows())) + "\\n")\n    return 0\n\n\ndef cmd_answers() -> int:\n    print("ANSWER KEY (instructors)\\n")\n    for e in load_golden():\n        print(f"  {e[\'id\']}  {e[\'kind\']:<11} → {e[\'memory_effect\']}   ({e[\'question\']})")\n    return 0\n']
for index, source in enumerate(NOTEBOOK_SOURCES):
    exec(compile(source, f'<notebook-section-{index}>', 'exec'), globals())

def main():
    parser = argparse.ArgumentParser(description="Week 15 Memory-Honesty Drill")
    commands = parser.add_subparsers(dest="command", required=True)

    commands.add_parser("compare")
    commands.add_parser("verdict")

    ids = [f"Q{i}" for i in range(1, 10)]
    run = commands.add_parser("run")
    run.add_argument("question", choices=ids)

    grade = commands.add_parser("grade")
    grade.add_argument("question", choices=ids)
    grade.add_argument("effect", choices=["helps", "hurts", "neutral"])

    args = parser.parse_args()

    if args.command == "compare":
        return cmd_compare()
    if args.command == "verdict":
        return cmd_verdict()
    if args.command == "run":
        return cmd_run(args.question)
    return cmd_grade(args.question, args.effect)


if __name__ == "__main__":
    raise SystemExit(main())
